<script setup>
import { computed, onMounted, ref } from "vue";
import { api, getSavedEmployee, normalizeList } from "../services/api";
const items=ref([]),loading=ref(true),saving=ref(false),error=ref(""),success=ref(""),canManage=ref(false);
const form=ref({title:"",body:"",link:"",expiresAt:"",status:"Draft"});
const employee=computed(()=>getSavedEmployee());
async function load(){loading.value=true;error.value="";try{const r=await api.listAnnouncements();items.value=normalizeList(r,["announcements"]);canManage.value=Boolean(r?.canManage||r?.data?.canManage);}catch(e){error.value=e.message||"Unable to load announcements."}finally{loading.value=false}}
async function save(){error.value="";success.value="";if(!form.value.title.trim()||!form.value.body.trim()){error.value="Enter a title and announcement message.";return} saving.value=true;try{await api.createAnnouncement({...form.value,expiresAt:form.value.expiresAt||null});success.value=form.value.status==="Published"?"Announcement published to the company home page.":"Draft saved.";form.value={title:"",body:"",link:"",expiresAt:"",status:"Draft"};await load()}catch(e){error.value=e.message||"Unable to save announcement."}finally{saving.value=false}}
async function setStatus(item,status){try{await api.updateAnnouncement(item._id,{status});await load()}catch(e){error.value=e.message||"Unable to update announcement."}}
async function archive(item){if(!confirm(`Archive “${item.title}”?`))return;try{await api.archiveAnnouncement(item._id);await load()}catch(e){error.value=e.message||"Unable to archive announcement."}}
onMounted(load);
</script>
<template><div class="experience-page announcement-admin-page"><header class="page-intro-row"><div><span class="eyebrow">COMPANY COMMUNICATION</span><h1>Announcements</h1><p>Publish company-wide updates that appear in the Home page announcement banner.</p></div></header><div v-if="error" class="alert alert-error">{{error}}</div><div v-if="success" class="alert alert-success">{{success}}</div><section v-if="canManage" class="workspace-panel announcement-editor"><h2>Create announcement</h2><form @submit.prevent="save"><label class="form-field">Title<input v-model="form.title" class="input" maxlength="160" required placeholder="e.g. Planned network maintenance" /></label><label class="form-field">Announcement message<textarea v-model="form.body" class="textarea" rows="4" maxlength="8000" required placeholder="Write the update employees need to know…"></textarea></label><div class="form-two-col"><label class="form-field">Optional link<input v-model="form.link" class="input" type="url" placeholder="https://…" /></label><label class="form-field">Expiry date<input v-model="form.expiresAt" class="input" type="date" /></label></div><label class="form-field">Publication status<select v-model="form.status" class="input"><option>Draft</option><option>Published</option></select></label><button class="action-primary" type="submit" :disabled="saving">{{saving?'Saving…':form.status==='Published'?'Publish announcement':'Save draft'}}</button></form></section><section class="workspace-panel announcement-list"><div class="panel-heading"><div><span class="eyebrow">PUBLICATION BOARD</span><h2>{{canManage?'Manage announcements':'Published announcements'}}</h2></div><button class="action-secondary" type="button" @click="load">Refresh</button></div><div v-if="loading" class="panel-empty">Loading announcements…</div><div v-else-if="!items.length" class="panel-empty">No announcements available.</div><article v-for="item in items" :key="item._id" class="announcement-row"><div><span class="announcement-status" :class="'status-'+String(item.status).toLowerCase()">{{item.status}}</span><h3>{{item.title}}</h3><p>{{item.body}}</p><a v-if="item.link" :href="item.link" target="_blank" rel="noopener noreferrer">Open related link ↗</a><small>By {{item.author?.firstName||'Employee'}} {{item.author?.lastName||''}} · {{item.publishedAt?new Date(item.publishedAt).toLocaleString():'Not published'}}</small></div><div v-if="canManage" class="announcement-row-actions"><button v-if="item.status!=='Published'" class="action-secondary" @click="setStatus(item,'Published')">Publish</button><button v-if="item.status==='Published'" class="action-secondary" @click="setStatus(item,'Draft')">Unpublish</button><button class="action-secondary" @click="archive(item)">Archive</button></div></article></section></div></template>
<style scoped>.announcement-editor,.announcement-list{padding:24px;margin-bottom:20px}.announcement-editor form{display:grid;gap:14px}.announcement-editor h2,.announcement-list h2{margin:0 0 16px}.announcement-row{display:flex;justify-content:space-between;gap:18px;padding:18px 0;border-top:1px solid var(--mf-border)}.announcement-row>div:first-child{min-width:0}.announcement-row h3{margin:8px 0}.announcement-row p{white-space:pre-wrap;line-height:1.65}.announcement-row small{display:block;margin-top:12px;color:var(--mf-muted)}.announcement-row a{color:var(--mf-primary)}.announcement-status{display:inline-block;padding:4px 8px;border-radius:99px;background:var(--mf-surface-soft);font-size:10px}.status-published{color:#15803d}.announcement-row-actions{display:flex;align-items:flex-start;gap:8px;flex-wrap:wrap}.announcement-row-actions button{white-space:nowrap}@media(max-width:650px){.announcement-editor,.announcement-list{padding:15px}.announcement-row{flex-direction:column}.announcement-row-actions{width:100%}.announcement-row-actions button{flex:1}}</style>
